package com.tripmateai.controller;
import com.tripmateai.dto.request.trip.*; import com.tripmateai.dto.response.ApiResponse; import com.tripmateai.dto.response.trip.*; import com.tripmateai.service.TripService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
/** Authenticated endpoints for managing the current user's trips. */
@RestController @RequestMapping("/trips") @RequiredArgsConstructor public class TripController {private final TripService service; @PostMapping public ResponseEntity<ApiResponse<TripResponse>> create(@Valid @RequestBody CreateTripRequest r){return ResponseUtils.created(service.createTrip(r),"Trip created");} @GetMapping public ResponseEntity<ApiResponse<Page<TripSummaryResponse>>> mine(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="newest") String sort){return ResponseUtils.success(service.getMyTrips(page,size,sort),"Trips retrieved");} @GetMapping("/saved") public ResponseEntity<ApiResponse<Page<TripSummaryResponse>>> saved(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return ResponseUtils.success(service.getSavedTrips(page,size),"Saved trips retrieved");} @GetMapping("/previous") public ResponseEntity<ApiResponse<Page<TripSummaryResponse>>> previous(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return ResponseUtils.success(service.getPreviousTrips(page,size),"Previous trips retrieved");} @PostMapping("/{id}/duplicate") public ResponseEntity<ApiResponse<TripResponse>> duplicate(@PathVariable Long id,@Valid @RequestBody DuplicateTripRequest r){return ResponseUtils.created(service.duplicateTrip(id,r),"Trip duplicated");} @PostMapping("/{id}/save") public ResponseEntity<ApiResponse<Void>> save(@PathVariable Long id){service.saveTrip(id);return ResponseUtils.success(null,"Trip saved");} @DeleteMapping("/{id}/save") public ResponseEntity<ApiResponse<Void>> unsave(@PathVariable Long id){service.unsaveTrip(id);return ResponseUtils.success(null,"Trip unsaved");} @GetMapping("/{id}") public ResponseEntity<ApiResponse<TripResponse>> get(@PathVariable Long id){return ResponseUtils.success(service.getTripById(id),"Trip retrieved");} @PutMapping("/{id}") public ResponseEntity<ApiResponse<TripResponse>> update(@PathVariable Long id,@Valid @RequestBody UpdateTripRequest r){return ResponseUtils.success(service.updateTrip(id,r),"Trip updated");} @DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.deleteTrip(id);return ResponseUtils.success(null,"Trip deleted");}}
